"""Regenerates vectors/compact_vectors.json from the Python compact codec (spec/PROTOCOL.md, "Compact protocol").

Run from the repo root after adding a case:  python tools/gen_compact_vectors.py
Every other implementation (the app's, the Arduino library's) must produce the same bytes.
"""
import json

from allsense_testkit import compact as ac

cases = {
    "note": "Generated by tools/gen_compact_vectors.py; every compact-protocol implementation must produce these bytes.",
    "crc16": [{"data_ascii": "123456789", "crc": "29b1"}],
    "cobs": [
        {"raw": raw, "encoded": ac.cobs_encode(bytes.fromhex(raw)).hex()}
        for raw in ["00", "0000", "001100", "11220033", "11223344", "11000000", ""]
    ],
    "frames": [
        {"what": "SUBSCRIBE stream 1, 50 Hz, accelerometer", "payload": ac.subscribe(1, 50.0, "accelerometer").hex(),
         "frame": ac.frame(ac.subscribe(1, 50.0, "accelerometer")).hex()},
        {"what": "DATA stream 3, seq 513, t 123456789 us, accuracy 3, values (0, 1.5, -9.81)",
         "payload": ac.data(3, 513, 123456789, 3, (0.0, 1.5, -9.81)).hex(),
         "frame": ac.frame(ac.data(3, 513, 123456789, 3, (0.0, 1.5, -9.81))).hex()},
        {"what": "PING token 0x01020304", "payload": ac.ping(0x01020304).hex(), "frame": ac.frame(ac.ping(0x01020304)).hex()},
        {"what": "HELLO from a board called x", "payload": ac.hello("x").hex(), "frame": ac.frame(ac.hello("x")).hex()},
    ],
}
with open("vectors/compact_vectors.json", "w", encoding="utf-8") as f:
    json.dump(cases, f, indent=1)
    f.write("\n")
print("wrote vectors/compact_vectors.json")
